function travel_table_insert(&$error_message = '') {
	global $Translation;

	// mm: can member insert record?
	$arrPerm = getTablePermissions('travel_table');
	if(!$arrPerm['insert']) {
		$error_message = $Translation['no insert permission'];
		return false;
	}

	$data = [
		'first_name' => Request::val('first_name', ''),
		'last_name' => Request::val('last_name', ''),
		'age' => Request::val('age', ''),
		'gender' => Request::val('gender', ''),
		'mobile_number' => Request::val('mobile_number', ''),
		'date_from' => Request::dateComponents('date_from', ''),
		'date_to' => Request::dateComponents('date_to', ''),
		'travel_description' => br2nl(Request::val('travel_description', '')),
		'approved_by' => Request::lookup('approved_by', ''),
		'remarks' => br2nl(Request::val('remarks', '')),
		'created_by' => parseCode('<%%creatorUsername%%>', true),
		'created_at' => parseCode('<%%creationDateTime%%>', true),
	];

	// record owner is current user
	$recordOwner = getLoggedMemberID();

	$recID = tableInsert('travel_table', $data, $recordOwner, $error_message);

	// if this record is a copy of another record, copy children if applicable
	if(strlen(Request::val('SelectedID')) && $recID !== false)
		travel_table_copy_children($recID, Request::val('SelectedID'));

	return $recID;
}

function travel_table_copy_children($destination_id, $source_id) {
	global $Translation;
	$requests = []; // array of curl handlers for launching insert requests
	$eo = ['silentErrors' => true];
	$safe_sid = makeSafe($source_id);
	$currentUsername = getLoggedMemberID();
	$errorMessage = '';

	// launch requests, asynchronously
	curl_batch($requests);
}

