function travel_table_update(&$selected_id, &$error_message = '') {
	global $Translation;

	// mm: can member edit record?
	if(!check_record_permission('travel_table', $selected_id, 'edit')) return false;

	$data = [
		'first_name' => Request::val('first_name', ''),
		'last_name' => Request::val('last_name', ''),
		'age' => Request::val('age', ''),
		'gender' => Request::val('gender', ''),
		'mobile_number' => Request::val('mobile_number', ''),
		'date_from' => Request::dateComponents('date_from', ''),
		'date_to' => Request::dateComponents('date_to', ''),
		'travel_description' => br2nl(Request::val('travel_description', '')),
		'approved_by' => Request::lookup('approved_by', ''),
		'remarks' => br2nl(Request::val('remarks', '')),
		'last_updated_by' => parseCode('<%%editorUsername%%>', false),
		'last_updated_at' => parseCode('<%%editingDateTime%%>', false),
	];

	// get existing values
	$old_data = getRecord('travel_table', $selected_id);
	if(is_array($old_data)) {
		$old_data = array_map('makeSafe', $old_data);
		$old_data['selectedID'] = makeSafe($selected_id);
	}

	$data['selectedID'] = makeSafe($selected_id);

	// hook: travel_table_before_update
	if(function_exists('travel_table_before_update')) {
		$args = ['old_data' => $old_data];
		if(!travel_table_before_update($data, getMemberInfo(), $args)) {
			if(isset($args['error_message'])) $error_message = $args['error_message'];
			return false;
		}
	}

	$set = $data; unset($set['selectedID']);
	foreach ($set as $field => $value) {
		$set[$field] = ($value !== '' && $value !== NULL) ? $value : NULL;
	}

	if(!update(
		'travel_table', 
		backtick_keys_once($set), 
		['`id`' => $selected_id], 
		$error_message
	)) {
		echo $error_message;
		echo '<a href="travel_table_view.php?SelectedID=' . urlencode($selected_id) . "\">{$Translation['< back']}</a>";
		exit;
	}


	update_calc_fields('travel_table', $data['selectedID'], calculated_fields()['travel_table']);

	// hook: travel_table_after_update
	if(function_exists('travel_table_after_update')) {
		if($row = getRecord('travel_table', $data['selectedID'])) $data = array_map('makeSafe', $row);

		$data['selectedID'] = $data['id'];
		$args = ['old_data' => $old_data];
		if(!travel_table_after_update($data, getMemberInfo(), $args)) return;
	}

	// mm: update record update timestamp
	set_record_owner('travel_table', $selected_id);
}

